    "questionAr": "أُطلقت رصاصة كتلتها $m_1 = 10\\text{ جم}$ أفقياً بسرعة $u = 300\\text{ م/ث}$ على كتلة ساكنة كتلتها $m_2 = 490\\text{ جم}$ موضوعة على سطح أفقي خشن (معامل الاحتكاك $\\mu = 0.25$). فإذا استقرت الرصاصة داخل الكتلة، احسب المسافة $s$ التي تقطعها حتى تسكن ($g = 9.8\\text{ م/ث²}$).",
