    "hintAr": "احسب السرعة المشتركة $v' = \\frac{m_1 u}{m_1 + m_2}$، ثم العجلة $a = \\mu g = 2.45\\text{ م/ث²}$، والمسافة $s = \\frac{v'^2}{2a}$.",
