    "questionAr": "سقطت مطرقة كتلتها $M = 400\\text{ كجم}$ سقوطاً حراً من ارتفاع $4.9\\text{ م}$ على وتد كتلته $m = 100\\text{ كجم}$. تحركا معاً وغاصا في الأرض مسافة $s = 0.06\\text{ م}$ حتى السكون. احسب متوسط قوة مقاومة الأرض $R$ ($g = 9.8\\text{ م/ث²}$).",
