    "correctIndex": 0,
    "hintEn": "Hammer speed before impact is $9.8\\text{ m/s}$. Common speed $v' = 7.84\\text{ m/s}$. Deceleration $a = \\frac{v'^2}{2s}$. Equation of motion: $(M+m)g - R = -(M+m)a$.",
    "hintAr": "سرعة المطرقة قبل الصدم $9.8\\text{ م/ث}$. السرعة المشتركة $v' = 7.84\\text{ م/ث}$. العجلة $a = \\frac{v'^2}{2s}$. معادلة الحركة: $(M+m)g - R = -(M+m)a$.",
