      "3. Deceleration during penetration: $a = \\frac{(7.84)^2}{2(0.06)} \\approx 512.21\\text{ m/s}^2$.",
      "4. Dynamic resistance equation: $R = (M + m)(g + a) = 500(9.8 + 512.21) \\approx 261005\\text{ N}$."
